//! ONE global SCC/summary over the actual retained Kind24 original graph.
use super::*;
use dm_analysis::checker_effects::{CompactEffectScc,OwnedCompactEffectSummary,EffectSource};
pub(super) const SUMMARY:Kind=Kind(25);
pub(crate) struct NativeEffectSummary{payload:Option<Arc<SummaryPayload>>}
struct SummaryPayload{summary:OwnedCompactEffectSummary,graph:Arc<global_graph::NativeEffectGraph>,lease:graph_work::GraphLease}
impl Drop for NativeEffectSummary{fn drop(&mut self){if let Some(payload)=self.payload.take().and_then(Arc::into_inner){let SummaryPayload{summary,graph,lease}=payload;drop(summary);drop(graph);drop(lease);}}}
impl NativeEffectSummary{
 pub(super) fn original_report_inputs(&self,source:&EffectSource<'_>)->Result<(&OwnedCompactEffectSummary,&dm_analysis::checker_effects::RetainedEffectGraph),dm_analysis::policy_body_demand::PolicyFailure>{self.payload().graph.current(source)?;Ok((&self.payload().summary,self.payload().graph.original_report_graph()))}

 fn payload(&self)->&SummaryPayload{self.payload.as_deref().expect("sealed global effect summary")}
 pub(crate) fn has_effect(&self,source:&EffectSource<'_>,node:usize)->Result<Option<bool>,dm_analysis::policy_body_demand::PolicyFailure>{self.payload().graph.current(source)?;Ok(self.payload().summary.node_has_effect(node))}
 pub(crate) fn retained_charge(&self)->Option<usize>{self.payload().summary.retained_charge()?.checked_add(Self::coordination_charge())}
 fn coordination_charge()->usize{std::mem::size_of::<SummaryPayload>().saturating_sub(std::mem::size_of::<OwnedCompactEffectSummary>())}
 pub(crate) fn visit_storage(&self,mut visit:impl FnMut(Storage)){let payload=self.payload();payload.summary.visit_storage(|owner,address,logical,capacity|visit(Storage::Buffer{owner,address,logical,capacity}));payload.graph.visit_storage(&mut visit);visit(Storage::Buffer{owner:"purity.global_summary_completion",address:Arc::as_ptr(&payload.lease.completion) as usize,logical:std::mem::size_of::<std::sync::atomic::AtomicBool>(),capacity:std::mem::size_of::<std::sync::atomic::AtomicBool>()});visit(Storage::Buffer{owner:"purity.global_summary_payload",address:payload as *const SummaryPayload as usize,logical:std::mem::size_of::<SummaryPayload>(),capacity:std::mem::size_of::<SummaryPayload>()});}
}
impl graph_work::RetainedHandle for NativeEffectSummary{fn fingerprint(&self,_:Key)->u128{let mut hash=xxhash_rust::xxh3::Xxh3::new();hash.update(b"original-effect-summary-retained-graph-v1");hash.update(&self.payload().summary.content_fingerprint().to_le_bytes());hash.update(&self.payload().graph.original_report_graph().report_fingerprint().to_le_bytes());hash.digest128()}type Data=(OwnedCompactEffectSummary,Arc<global_graph::NativeEffectGraph>);fn coordination_charge()->usize{Self::coordination_charge()}fn issue((summary,graph):Self::Data,ledger:Arc<Mutex<Ledger>>,completion:Arc<std::sync::atomic::AtomicBool>)->Arc<Self>{Arc::new(Self{payload:Some(Arc::new(SummaryPayload{summary,graph,lease:graph_work::GraphLease{ledger,completion}}))})}fn retained_charge(&self)->Option<usize>{Self::retained_charge(self)}}
struct SummaryParams{base:Params,width:usize}
fn summary_key(input:&EffectInput,width:usize)->Key{key(SUMMARY,input,width as u128)}
pub(super) fn register(db:&Db,ledger:Arc<Mutex<Ledger>>,registry:SourceRegistry){db.define(SUMMARY,"native-original-global-effect-summary",move|ctx,raw|{
 let params=raw.downcast_ref::<SummaryParams>().expect("global summary params");let k=params.base.key;pages::typed_publication(&ledger,k)?;let input=params.base.input.upgrade().ok_or(QueryError::Missing(k))?;
 checked_sources_using::<ReadFailure>(&input,&params.base.sources,&registry,||crate::daemon::control::checkpoint().map_err(|actual|ReadFailure::Query(QueryError::operational(k,actual)))).map_err(|error|match error{ReadFailure::Query(error)=>error,ReadFailure::Semantic(_)=>QueryError::Missing(k)})?;
 let graph=match global_graph::obtain(ctx,&ledger,&input,&params.base.sources,params.width){Ok(graph)=>graph,Err(ReadFailure::Query(actual))=>return Err(actual),Err(ReadFailure::Semantic(message))=>{let bytes=message.capacity();return finish_using::<NativeEffectSummary>(&ledger,k,Err(message),bytes,pages::typed_publication,|key,actual|QueryError::operational(key,std::io::Error::new(std::io::ErrorKind::OutOfMemory,actual)))}};
 let source=EffectSource::new(input.archive(),input.profile()).map_err(|error|match policy_read_failure(k,error){ReadFailure::Query(error)=>error,ReadFailure::Semantic(_)=>QueryError::Missing(k)})?;let current=graph.current(&source).map_err(|error|match policy_read_failure(k,error){ReadFailure::Query(error)=>error,ReadFailure::Semantic(_)=>QueryError::Missing(k)})?;
 // The graph child is already retained in this SAME ledger. This operation's
 // view therefore excludes its charge once. No standalone graph-overlap charge
 // is applied again. All SCC/summary phases fit this precharged conservative
 // aggregate; there are no nested queries during either scalar phase.
 let admission=pages::page_execution_admission(&ledger).map_err(|_|QueryError::Missing(k))?;let mut work=graph_work::GraphWork::new(Arc::clone(&ledger),k);let nodes=current.len();let reserve=CompactEffectScc::work_charge(nodes).and_then(|n|CompactEffectScc::summary_work_charge_bound(nodes).and_then(|m|n.checked_add(m))).ok_or_else(||QueryError::operational(k,std::io::Error::new(std::io::ErrorKind::OutOfMemory,"global effect summary work envelope overflow")))?;work.reserve(reserve).map_err(|actual|QueryError::operational(k,actual))?;
 let computed=(||{let scc=CompactEffectScc::compute_checked(nodes,&admission,|node,next,_|current.successor(node,next),&mut crate::daemon::control::checkpoint)?;scc.into_summary_checked(&admission,|node,_|current.direct_effect(node).ok_or_else(||"global effect seed outside original roster".into()),|node,next,_|current.successor(node,next),&mut crate::daemon::control::checkpoint)})();latch_transient_denial(&ledger,&admission);
 match split_transport(computed.map_err(|error|policy_read_failure(k,error)))?{Ok(summary)=>{drop(current);work.publish_data::<NativeEffectSummary>((summary,graph))},Err(message)=>{drop(work);let bytes=message.capacity();finish_using::<NativeEffectSummary>(&ledger,k,Err(message),bytes,pages::typed_publication,|key,actual|QueryError::operational(key,std::io::Error::new(std::io::ErrorKind::OutOfMemory,actual)))}}
});}

impl QueryDb{
 pub(crate) fn native_effect_source_summary(&self,input:&Arc<EffectInput>,scope:&crate::runner_host::query_snapshot::PurityScope<'_>,width:usize)->std::io::Result<Arc<NativeEffectSummary>>{
  crate::daemon::control::checkpoint()?;scope.validate(self,input).map_err(std::io::Error::other)?;self.prune_purity();let _gate=self.purity.gate.lock().unwrap_or_else(|e|e.into_inner());scope.validate(self,input).map_err(std::io::Error::other)?;
  {let mut ledger=self.purity.ledger.lock().unwrap_or_else(|e|e.into_inner());ledger.denied=false;ledger.aborted=None;}
  let result=(||->Result<Arc<NativeEffectSummary>,ReadFailure>{
   if !input.is_source_page_context()||width==0||width>dm_analysis::checker_effects::MAX_EVENTS{return Err("effect global graph requires original source-page context/window".into())}
   let key=summary_key(input,width);let sources=self.purity_sources_using::<ReadFailure>(input,|keys|checked_sources_using::<ReadFailure>(input,keys,&self.sources,||crate::daemon::control::checkpoint().map_err(|actual|ReadFailure::Query(QueryError::operational(key,actual)))),|actual|ReadFailure::Query(QueryError::operational(key,std::io::Error::new(std::io::ErrorKind::OutOfMemory,actual))))?;
   let value=obtain_using(&self.purity.ledger,input,&sources,width,|key,params|self.db.get::<Result<Arc<NativeEffectSummary>,String>>(key,params))?;
   crate::daemon::control::checkpoint().map_err(|actual|ReadFailure::Query(QueryError::operational(key,actual)))?;scope.validate(self,input)?;let source=EffectSource::new(input.archive(),input.profile()).map_err(|error|policy_read_failure(key,error))?;value.payload().graph.current(&source).map_err(|error|policy_read_failure(key,error))?;Ok(value)
  })();
  match result{Err(ReadFailure::Query(error))=>Err(pages::restore_graph_error(&self.purity.ledger,error)),other=>{crate::daemon::control::checkpoint()?;if self.purity.ledger.lock().unwrap_or_else(|e|e.into_inner()).denied{return Err(std::io::Error::new(std::io::ErrorKind::OutOfMemory,"native effect global graph retained admission exhausted"))}match other{Ok(value)=>Ok(value),Err(ReadFailure::Semantic(message))=>Err(std::io::Error::other(message)),Err(ReadFailure::Query(_))=>unreachable!()}}}
 }
}

fn obtain_using(ledger:&Arc<Mutex<Ledger>>,input:&Arc<EffectInput>,sources:&Arc<Vec<Key>>,width:usize,get:impl FnOnce(Key,Arc<SummaryParams>)->Result<Arc<Result<Arc<NativeEffectSummary>,String>>,QueryError>)->Result<Arc<NativeEffectSummary>,ReadFailure>{let key=summary_key(input,width);let _node=node_admission(ledger,input,key,std::mem::size_of::<SummaryParams>())?;{let mut ledger=ledger.lock().unwrap_or_else(|e|e.into_inner());let old=ledger.nodes.get(&key).ok_or("summary node unavailable")?.observed_edges;ledger.admit(4usize.saturating_sub(old).saturating_mul(EDGE_BOUND))?;ledger.nodes.get_mut(&key).unwrap().observed_edges=old.max(4);}let params=Arc::new(SummaryParams{base:Params{input:Arc::downgrade(input),key,ordinal:0,sources:sources.clone(),policy:Weak::new()},width});remember_params(ledger,input,key,&params);let value=get(key,params).map_err(ReadFailure::Query)?.as_ref().clone().map_err(ReadFailure::Semantic)?;let source=EffectSource::new(input.archive(),input.profile()).map_err(|error|policy_read_failure(key,error))?;value.original_report_inputs(&source).map_err(|error|policy_read_failure(key,error))?;Ok(value)}

pub(super) fn obtain(ctx:&mut dm_query::Ctx<'_>,ledger:&Arc<Mutex<Ledger>>,input:&Arc<EffectInput>,sources:&Arc<Vec<Key>>,width:usize)->Result<Arc<NativeEffectSummary>,ReadFailure>{obtain_using(ledger,input,sources,width,|key,params|ctx.get::<Result<Arc<NativeEffectSummary>,String>>(key,params))}
